add_action('admin_init', function () {
    if (empty($_GET['mg_seed_texts']) || !current_user_can('manage_options')) return;
    header('Content-Type: text/plain; charset=utf-8');
    $data = json_decode(<<<'NOWDOC_END'
{"projects": {"Stage Somedia": {"einleitung": ["Im Wahlmodul Stage Somedia habe ich drei Wochen bei der Kommunikationsagentur Communicaziun in Chur gearbeitet, vom 20. Juli bis 7. August 2026. Eine Woche war ich im Videoteam, zwei Wochen im Marketingteam. So konnte ich sehen, wie eine Agentur Video, Online- und Offlinemarketing im Alltag verbindet."], "aufgaben": ["Videoschnitt und Color Grading in Premiere Pro", "Grafische Mitarbeit an einem Pitch", "Filmkonzept mit Content-Kalender", "Einblick ins Online- und Offlinemarketing-Team", "Glion Run: Name, Logo und Hauptbotschaft, Marketingmassnahmen, Timing, Redaktionsplan sowie Website- und Instagram-Mockup"], "karten": [["Glion Run", "Eigene Arbeit: das fiktive Kommunikationskonzept für einen Stadtlauf in Ilanz. Es umfasst Namen und Hauptbotschaft, Logo, Marketingmassnahmen, Timing und einen Redaktionsplan für Social Media. Das Website-Mockup entstand in Figma, das Design in Canva."], ["Im Videoteam", "Material in Premiere Pro geschnitten und ein Color Grading umgesetzt."], ["Im Marketing", "Grafisch an einem Pitch mitgearbeitet, ein Filmkonzept mit Content-Kalender erarbeitet und Einblick in die Planung von Online- und Offlinemassnahmen erhalten."]], "prozess": "Besonders spannend war für mich, wie viel Abstimmung hinter einem fertigen Projekt steckt. Ich habe gelernt, Ideen früh zu zeigen, Feedback aufzunehmen und Entwürfe schnell zu überarbeiten. Diese Arbeitsweise möchte ich in meinem Studium und in meinem nächsten Job weiterführen.", "schritte": ["Eine Woche im Videoteam", "Zwei Wochen im Marketingteam", "Eigenes Konzept «Glion Run» entwickeln", "Mockup in Figma und Design in Canva umsetzen"], "mitarbeit": "", "links": [["Glion Run: Website-Mockup (Figma)", "https://www.figma.com/make/xoGUuUDD46NLuBufMuUf9O/www.glionrun.ch?code-node-id=0-6&p=f&t=Wm3pHJaliO6OIYtE-0&fullscreen=1"], ["Glion Run: Design (Canva)", "https://canva.link/15kau5eo8nl5jgs"]]}, "Repower Social Recruiting": {"einleitung": ["Repower sucht Fachkräfte für spezialisierte Berufe in Graubünden, und das in einem hart umkämpften Arbeitsmarkt. Im Major Communications Management haben wir zu dritt eine Social-Recruiting-Strategie entwickelt, die Repower intern und mit echten Mitarbeitenden umsetzen kann."], "aufgaben": ["Lead Design: einheitliche visuelle Gestaltung der Kampagne", "Gestaltung der Pitch-Präsentation und der Prototypen (Landingpage, Videos)", "Mitarbeit an Insights, Strategie und Kreation im Team", "Präsentation der Prototypen und Einarbeitung des Feedbacks von Repower"], "karten": [["Leitidee «Strom, ledig, sucht»", "Repower als «perfect Match»."], ["Zwei Videoformate", "Im ersten erzählen echte Quereinsteiger:innen ihre Erfolgsgeschichte als Lovestory. Im zweiten beantworten Passant:innen auf der Strasse die Frage nach dem «Geheimnis einer glücklichen Beziehung», und die Antworten werden mit den Werten von Repower verknüpft."], ["Kanäle und Landingpage", "Die Kurzvideos für Instagram, TikTok und YouTube Shorts führen über eine Landingpage bis zur Bewerbung."], ["Übergabe", "Konzept, How-to-Leitfäden, vier Prototyp-Videos und ein Landingpage-Prototyp."]], "prozess": "Grundlage waren Fokusgruppen beim Repower-Tag in Küblis, Personas sowie Analysen zu Marke, Markt und bisherigem Employer Branding. Dabei zeigte sich ein blinder Fleck: Viele geeignete Fachkräfte sprechen die Stellen gar nicht an, weil sie nicht wissen, dass sie infrage kommen. Unsere Zielgruppe wurden deshalb Quereinsteiger:innen zwischen 25 und 45.", "schritte": ["Fokusgruppen beim Repower-Tag in Küblis", "Personas und Analysen zu Marke, Markt und Employer Branding", "Zielgruppe festlegen: Quereinsteiger:innen zwischen 25 und 45", "Leitidee und Videoformate entwickeln", "Prototypen bauen und Feedback von Repower einarbeiten"], "mitarbeit": "Alisha Künzi, Kilian Züger", "links": [["Zum LinkedIn-Post", "https://www.linkedin.com/feed/update/urn:li:activity:7480593806564765696/"], ["Abschlusspräsentation ansehen (Canva)", "https://www.canva.com/design/DAHKBH834mU/7XiKEQDDTP0J5xt54R26CQ/view"], ["Landingpage-Prototyp ansehen", "https://quereinstieg-repower.lovable.app"]]}, "Bad Ragartz": {"einleitung": ["Die Bad Ragartz ist eine Freiluft-Skulpturenausstellung, die alle drei Jahre in Bad Ragaz, Vaduz und im Alten Bad Pfäfers stattfindet. Im Minor Event-Inszenierung haben wir für die 10. Ausgabe 2027 den Bahnhof Bad Ragaz als zentralen Ankunfts- und Informationspunkt gestaltet."], "aufgaben": ["Konzeptarbeit und Ideenentwicklung im Team", "Gestaltung des Moodboards (Fonts, Farbwelt, Stimmung)", "Layout und Gestaltung des Konzeptdokuments in InDesign (Inhaltsverzeichnis, Seitenaufbau, Typografie)", "Mitarbeit an der Rauminszenierung für Wartehalle und Unterführung"], "karten": [["Kunst und Natur", "Linien in der Ausstellungsfarbe führen vom Bahnhof Richtung Skulpturenweg, ein baumartiges Regal bildet das Highlight der Halle, und Holzlamellen an der Decke sorgen für Tiefe."], ["Wiederverwendbar", "Möbel und Materialien sind wiederverwendbar gedacht, damit sie nach der Ausstellung weiterverwendet werden können."], ["Welcome Desk", "Als Kontrast zu den runden Formen hat der Welcome Desk eine eckige Form. Er bietet Aufbewahrungsfächer und eine integrierte Garderobe."], ["Ohne Sound", "Bewusst haben wir auf Sound verzichtet, weil der Bahnhof ein öffentlicher Ort ist."]], "prozess": "Unter Berücksichtigung der Vorgaben haben wir verschiedene Ideen gesammelt und diese in einem Moodboard visualisiert.", "schritte": ["Ideen sammeln", "Moodboard mit Fonts, Farbwelt und Stimmung", "Konzeptdokument in InDesign gestalten", "Wartehalle und Unterführung inszenieren", "Visualisierungen erstellen"], "mitarbeit": "Julia Moos, Vianne Häfeli, Mark Hamann", "links": []}, "Multitalk Radio Calanda": {"einleitung": ["Multitalk ist eine gemeinsam mit zwei Kolleginnen entwickelte Radiosendung auf Radio Calanda, die alle zwei Wochen live ausgestrahlt und anschliessend als Podcast veröffentlicht wird. Das Gesprächsformat arbeitet mit wechselnden Oberthemen, zu denen jede Moderatorin eine eigene Rubrik einbringt. So entstehen unterschiedliche Perspektiven und inhaltliche Schwerpunkte innerhalb einer Sendung."], "aufgaben": ["Gestaltung des visuellen Auftritts (Logo, Bildmaterial)", "Produktion von Fotos und Grafiken für Website und Social Media", "Betreuung und Planung der Social-Media-Inhalte", "Mitarbeit bei Themenfindung und Sendungsvorbereitung", "Hosten der Radiosendung"], "karten": [["Live-Radio", "Die Sendung läuft alle zwei Wochen am Dienstag von 18:00 bis 19:30 Uhr live auf Radio Calanda."], ["Podcast", "Nach der Ausstrahlung erscheint jede Sendung als Podcast, zum Beispiel auf Spotify und Apple Podcasts."], ["Visueller Auftritt", "Logo, Fotos und Grafiken für Website und Social Media."]], "prozess": "Das Projekt entstand im Rahmen des Studiums und vermittelte mir einen praxisnahen Einblick in die Konzeption, Umsetzung und Kommunikation eines Audioformats im Live-Radio-Kontext.", "schritte": ["Themen finden und Rubriken planen", "Sendung vorbereiten", "Live hosten", "Als Podcast veröffentlichen", "Social Media betreuen"], "mitarbeit": "Laila, Alisha", "links": [["Radio Calanda", "https://radiocalanda.ch"], ["Multitalk auf Digezz", "https://www.digezz.ch/multitalk-uf-radio-calanda/"]]}, "Soziale Fachdienste": {"einleitung": ["Für die Sozialen Fachdienste AG habe ich ein Redesign der bestehenden Website entwickelt und umgesetzt. Ziel war es, die Inhalte klarer zu strukturieren, die Orientierung zu verbessern und einen ruhigen, zeitgemässen Auftritt zu schaffen."], "aufgaben": ["Konzeption und Gestaltung des visuellen Redesigns", "Überarbeitung von Struktur, Navigation und Seitenaufbau", "Gestaltung von Layout, Typografie und Farbwelt", "Umsetzung des Designs für die Website"], "karten": [["Klare Struktur", "Die Inhalte sind übersichtlicher gegliedert, und die Navigation ist verständlich."], ["Gute Lesbarkeit", "Der Fokus lag auf Lesbarkeit und einer Gestaltung, die den sensiblen Themenbereich unterstützt, ohne sich in den Vordergrund zu drängen."], ["Ruhiger Auftritt", "Zurückhaltende Farben, ruhiges Layout und ein zeitgemässer Look."]], "prozess": "Am Anfang standen drei Moodboards mit unterschiedlichen Ideen. Daraus ist der ruhige, zurückhaltende Auftritt entstanden.", "schritte": ["1. Idee: Die Homepage wechselt je nach Standort zwischen Grün und Blau", "2. Idee: farbig und frech, mit Illustrationen", "3. Idee: sehr minimalistisch in Grün und Blau, für die Standorte eine Illustration der Skyline", "Umsetzung als Website"], "mitarbeit": "", "links": [["Website ansehen", "https://www.sozialefachdienste.ch"]]}, "FHGR Merch": {"einleitung": ["Für das FHGR-Merch haben wir ein Rebranding entwickelt, das die visuelle Identität der Hochschule modern und tragbar aufgreift. Ziel war es, eine Kollektion zu gestalten, die von Studierenden gerne getragen wird und gleichzeitig die FHGR authentisch repräsentiert."], "aufgaben": ["Konzeption und Entwicklung des Rebrandings in Zusammenarbeit mit Jule Buchmann", "Erstellung von Moodboards, Skizzen und digitalen Mockups", "Gestaltung von Layouts, Typografie und Farbwelten", "Umsetzung und Präsentation der Designs für die Merch-Kollektion"], "karten": [["Calanda", "Bezug zur Region mit minimalistischen Höhenlinien und neutralen Farben, ergänzt durch den Claim «snow, mountains and deadlines»."], ["Typo", "Typografische Experimente mit Logo-Elementen, auffällige, aber klare Farbkombinationen und typografische Inszenierung des Claims."], ["Steinbock", "Stilisiertes Wappentier, grafisch abstrahiert, jung und verspielt, kombiniert mit auffälligen Farben und einem lässigen Look."]], "prozess": "Ausgehend von Feedback der Studierenden entstanden drei Designlinien.", "schritte": ["Feedback der Studierenden einholen", "Moodboards und Skizzen erarbeiten", "Digitale Mockups erstellen", "Designs umsetzen und präsentieren"], "mitarbeit": "Jule Buchmann", "links": [["Projekt auf Digezz", "https://www.digezz.ch/fhgr-merch-rebranding-snow-mountains-and-deadlines/"]]}, "Webdesign & Informatik": {"einleitung": ["Im Rahmen des Moduls Informatik habe ich mehrere Websites gestaltet und umgesetzt, wobei der Fokus auf Benutzerfreundlichkeit, klarer Struktur und ansprechender visueller Gestaltung lag.", "Die Websites Alohameter und Conversations entstanden in Zusammenarbeit mit meiner Kollegin Jule Buchmann. Für das Projekt Whisk & Bliss habe ich die Gestaltung vollständig eigenständig übernommen."], "aufgaben": ["UX- und UI-Konzeption in Figma, inklusive Wireframes und Prototyping", "Gestaltung von Layouts, Typografie, Farbwelt und visuellen Elementen", "Umsetzung der Designs in HTML, CSS und JavaScript (Alohameter & Conversations)", "Testing, Feedbackintegration und kontinuierliche Optimierung", "Zusammenarbeit bei Designentscheidungen und Projektkoordination"], "karten": [["AlohaMeter", "Zeigt live Temperatur und Windgeschwindigkeit rund um die Hawaii-Inseln Kauai, Oahu, Maui und Big Island."], ["Conversations", "Eine Website für Deeptalks, mit Fragen wie «Who's most likely to lose their phone for a day?»."], ["Whisk & Bliss", "Das UX- und UI-Design entstand komplett in Figma, inklusive Wireframes, interaktiver Prototypen und visueller Gestaltung. Das Projekt befindet sich aktuell noch in der Designphase."]], "prozess": "Wir entwickelten zunächst das UX-Design in Figma, um Benutzerfluss, Navigation und Layouts zu planen, und setzten die Designs danach in Visual Studio Code mit HTML, CSS und JavaScript um. Während des Projekts testeten wir die Interfaces, integrierten Feedback und optimierten kontinuierlich die Benutzererfahrung.", "schritte": ["Benutzerfluss, Navigation und Layouts in Figma planen", "Wireframes und interaktive Prototypen bauen", "Mit HTML, CSS und JavaScript umsetzen", "Interfaces testen und Feedback einarbeiten"], "mitarbeit": "Jule Buchmann (Alohameter, Conversations)", "links": [["AlohaMeter", "https://alohameter.melinagast.ch"], ["Conversations", "https://conversations.melinagast.ch"], ["Whisk & Bliss (Figma-Prototyp)", "https://www.figma.com/proto/QrrQkCKlSKEowqPeZndQwD/whisk---bliss?page-id=0%3A1&node-id=78-460&viewport=452%2C228%2C0.13&t=uLTzYb0vkLoHqVqW-1&scaling=min-zoom&content-scaling=fixed&starting-point-node-id=21%3A1462&show-proto-sidebar=1"]]}, "Dokumentarfilme": {"einleitung": ["Im Rahmen des Studiums habe ich an zwei dokumentarischen Filmprojekten mitgearbeitet: einem Kurzfilm (ca. 5 Minuten) sowie dem 15-minütigen Dokumentarfilm «Queer durch Berlin»."], "aufgaben": ["Projektleitung und Terminkoordination", "Kommunikation mit Protagonist:innen und Locations", "Transkription der Interviews für den Schnitt", "Mitwirkung an inhaltlicher Struktur und Dramaturgie"], "karten": [["Queer durch Berlin", "Der Film verbindet persönliche Erfahrungen queerer Menschen mit historischen Einordnungen und der heutigen queeren Szene Berlins. Gedreht wurde vor Ort in Berlin, unter anderem mit Protagonist:innen aus der Drag-Szene und im Schwulen Museum."], ["Was ich gelernt habe", "Die Filmprojekte haben mir gezeigt, wie entscheidend gute Vorbereitung, klare Rollen und sauberes Datenmanagement für dokumentarisches Arbeiten sind."]], "prozess": "Die Projekte umfassten den gesamten Produktionsprozess von der Konzeption über die Dreharbeiten bis zur Postproduktion. Die Arbeit im Team war klar strukturiert, gleichzeitig verlangten kurzfristige Änderungen, Absagen und technische Herausforderungen viel Flexibilität und Organisation.", "schritte": ["Konzeption", "Dreharbeiten", "Interviews transkribieren", "Postproduktion"], "mitarbeit": "", "links": [["Queer durch Berlin (YouTube)", "https://www.youtube.com/watch?v=YigXu5l9yMI"], ["Brennpunkt Welschdörfli (YouTube)", "https://www.youtube.com/watch?v=_bQ9u9dyQnw"]]}, "Sketch & Draw": {"einleitung": ["Im Rahmen des Moduls Sketch & Draw 1 entstand ein kaleidoskopisches Polyptychon zum Thema «Skizzen des Alltäglichen – der Weg eines Handschuhs». Die Arbeit erzählt in mehreren Bildern die Geschichte eines Handschuhs und folgt ihm durch unterschiedliche alltägliche Situationen und Räume."], "aufgaben": ["Entwicklung der Bildidee und narrativen Abfolge", "Fotografische Vorstudie und kompositorische Planung", "Analoge Zeichnungen mit Fokus auf Perspektive, Licht und Schatten"], "karten": [["Technik", "Gearbeitet wurde analog mit Bleistift auf A4-Papier. Die Zeichnungen fokussieren sich auf Form, Perspektive sowie Licht und Schatten."], ["Komposition", "Die Arbeit erstreckt sich über mehrere Seiten im Landscape-Format und bildet eine zusammenhängende visuelle Abfolge aus Detailansichten, räumlichen Situationen und Bewegung."], ["Gestaltungselemente", "Leerraum, Überlagerungen über den Blattrand hinweg sowie variierende Bildgrössen wurden gezielt eingesetzt."]], "prozess": "Unterschiedliche Einstellungsgrössen, Perspektiven und Bildausschnitte strukturieren die Erzählung.", "schritte": ["Bildidee und Ablauf entwickeln", "Fotografische Vorstudie", "Komposition planen", "Mit Bleistift zeichnen"], "mitarbeit": "", "links": []}, "Konzept RaBe": {"einleitung": ["Im Rahmen des Moduls «Schreiben und Sprechen III» haben Jule Buchmann und ich ein Kommunikationskonzept für RaBe entwickelt. Ziel war es, Kommunikationsziele zu definieren und konkrete Massnahmen umzusetzen, die sowohl inhaltlich als auch visuell überzeugen.", "Neben der Analyse der bestehenden Kommunikation, der Entwicklung von Zielgruppenprofilen und der Formulierung von Kernbotschaften haben wir einen grossen Teil des Designs übernommen."], "aufgaben": ["Mitarbeit bei Recherche, Analyse und Strategieentwicklung", "Mitgestaltung von Kernbotschaften und Kommunikationsplan", "Design und visuelle Umsetzung von Flyern, Flaggen und Website-Mockups", "Erstellung des finalen Konzepts als Dokumentation"], "karten": [["30 Jahre RaBe", "Kampagne zum Jubiläum, mit der Podcast-Serie «30 Jahre, 30 Stimmen», einer Social-Media-Challenge und Creator-Takeovers."], ["Flaggen und City Branding", "Spezielle Jubiläumsflaggen werden gratis an die Mitglieder gesendet und sind auf der Jubiläumswebsite kostenlos bestellbar."], ["Flyer und Plakate", "Gezielt an Hochschulen, Cafés, Festivals und kulturellen Hotspots verteilt. QR-Codes ermöglichen die direkte digitale Weiterführung."], ["One-Page-Website", "Speziell für die Kampagne lanciert, mit allen Angeboten, Aktionen und Events auf einen Blick."]], "prozess": "Wir arbeiteten iterativ, erstellten Moodboards und Mockups, testeten Varianten und passten diese nach Feedback an, um ein stimmiges und konsistentes visuelles Konzept zu entwickeln.", "schritte": ["Analyse der bestehenden Kommunikation", "Zielgruppenprofile und Kernbotschaften", "Moodboards und Mockups", "Varianten testen und nach Feedback anpassen", "Konzept als Dokumentation abschliessen"], "mitarbeit": "Jule Buchmann", "links": [["Kommunikationskonzept ansehen", "https://acrobat.adobe.com/id/urn:aaid:sc:EU:418c6470-bba7-428b-8ef3-61fac3d84e0b"]]}, "IPA Flower Experience": {"einleitung": ["Im Rahmen meiner Lehrabschlussarbeit (IPA) bei IKEA Dietlikon habe ich eine Verkaufsfläche (Vitality Media HFB 16) für den Sommerevent «Flower Experience» konzipiert und umgesetzt. Ziel war es, eine aufmerksamkeitsstarke Inszenierung zu gestalten, die sich klar von der Umgebung abhebt und das Hauptprodukt in den Fokus rückt."], "aufgaben": ["Eigenständige Konzeption und Gestaltung der gesamten Verkaufsfläche", "Analyse von Kundenfluss, Trends, Zielgruppe und Sortiment", "Entwicklung von zwei Gestaltungsideen inklusive Moodboards und Visualisierungen", "Präsentation, Entscheidungsfindung und Weiterentwicklung der finalen Idee", "Detailplanung (Grundriss, Produkte, Kosten, Zeitplan)", "Koordination von Verkauf, Haustechnik, Montage und Reinigung", "Umsetzung vor Ort sowie vollständige IPA-Dokumentation"], "karten": [["Flowerpower", "Die finale Gestaltung «Flowerpower» wurde ausgewählt, umgesetzt und dokumentiert."], ["Von der Idee zur Fläche", "Ich habe das Projekt eigenständig von der Idee bis zur realisierten Fläche geführt."], ["Trendanalyse", "Blumen, runde Formen, natürliche Materialien und «perfekte Imperfektion» prägten die Gestaltung."]], "prozess": "Nach der Analyse von Standort, Kundenfluss und Sortiment entwickelte ich zwei Gestaltungskonzepte, die ich präsentierte und weiter ausarbeitete.", "schritte": ["Standort, Kundenfluss und Sortiment analysieren", "Trendanalyse", "Zwei Gestaltungskonzepte mit Moodboards und Visualisierungen", "Präsentation und Entscheid für «Flowerpower»", "Detailplanung mit Grundriss, Kosten und Zeitplan", "Umsetzung vor Ort und Dokumentation"], "mitarbeit": "", "links": [["IPA-Dokumentation ansehen", "https://acrobat.adobe.com/id/urn:aaid:sc:EU:fb86db48-725a-47ba-a646-7e61c9e34e38"]]}, "Acne Studios": {"einleitung": ["Während meiner Polydesign-Lehre habe ich ein Gestaltungskonzept für einen Shop-in-Shop von Acne Studios umgesetzt. Ziel war es, die neue Kollektion «New Arrivals» attraktiv zu präsentieren und das Markenimage sichtbar zu machen."], "aufgaben": ["Eigenständige Materialrecherche und Moodboard-Erstellung", "Entwicklung und Umsetzung des Raum- und Farbkonzepts", "Gestaltung der Ausstellungselemente und visuellen Inszenierung", "Erstellung von Renderings, Layoutplänen und finalem Konzeptdossier"], "karten": [["Ausstellungselemente", "Bodenbelag, Spiegelwände, Deckenraster, Kleiderstangen, Wolkenpodeste, Beleuchtung und Logo-Positionierung."], ["Pläne und Renderings", "Renderings und Layoutpläne, alle Pläne im Massstab 1:50."], ["Konzeptdossier", "Das gesamte Konzept ist in einem Dossier dokumentiert."]], "prozess": "Ich habe den gesamten Prozess selbstständig übernommen. Varianten wurden getestet und iterativ angepasst, um ein stimmiges und konsistentes Konzept zu entwickeln.", "schritte": ["Marke analysieren", "Materialrecherche und Moodboards", "Raum- und Farbkonzept entwickeln", "Renderings und Layoutpläne erstellen", "Konzeptdossier abschliessen"], "mitarbeit": "", "links": [["Projekt ansehen", "https://acrobat.adobe.com/id/urn:aaid:sc:EU:4705f49f-aff1-465e-b9c1-ed7086fedc77"]]}}, "legal": {"Impressum": "<h2>Betreiberin</h2><p>Melina Gast<br>8303 Bassersdorf<br>Schweiz</p>\n<h2>Kontakt</h2><p>E-Mail: melina.gast@gmx.ch</p>\n<h2>Verantwortlich für den Inhalt</h2><p>Melina Gast</p>\n<h2>Entstehung</h2><p>Diese Website ist mein persönliches Portfolio. Sie ist im Ateliersemester IM5 im Studiengang Multimedia Production an der FHGR (Fachhochschule Graubünden) entstanden.</p>\n<h2>Haftungsausschluss</h2><p>Ich erstelle die Inhalte dieser Website mit grösster Sorgfalt. Für Richtigkeit, Vollständigkeit und Aktualität übernehme ich aber keine Gewähr.</p><p>Für Inhalte externer Websites, auf die ich verlinke, sind ausschliesslich deren Betreiber verantwortlich.</p>\n<h2>Urheberrecht</h2><p>Texte, Bilder, Grafiken, Audio- und Videoinhalte stammen von mir oder den bei den Projekten genannten Personen, zum Beispiel Jule Buchmann beim Projekt FHGR Merch. Eine Verwendung oder Weitergabe ist nur mit meiner schriftlichen Zustimmung erlaubt.</p>", "Datenschutz": "<h2>Verantwortliche</h2><p>Verantwortlich für die Bearbeitung von Personendaten auf dieser Website ist Melina Gast, 8303 Bassersdorf, Schweiz, E-Mail: melina.gast@gmx.ch.</p>\n<h2>Grundsatz</h2><p>Ich bearbeite Personendaten nur so weit, wie es für den Betrieb dieser Website und für die Beantwortung von Anfragen nötig ist. Grundlage ist das Schweizer Datenschutzgesetz (DSG).</p>\n<h2>Hosting und Server-Logs</h2><p>Beim Aufruf der Website speichert der Server technisch notwendige Daten, zum Beispiel IP-Adresse, Datum und Uhrzeit, aufgerufene Seite und Browsertyp. Diese Daten dienen dem sicheren Betrieb und werden nach kurzer Zeit gelöscht.</p>\n<h2>Kontakt per E-Mail</h2><p>Wenn du mir per E-Mail schreibst, bearbeite ich Name, E-Mail-Adresse und Nachricht, um dir zu antworten. Ich gebe diese Daten nicht weiter und lösche sie, sobald deine Anfrage erledigt ist und keine Aufbewahrungspflicht besteht.</p>\n<h2>Cookies und Analyse</h2><p>Diese Website setzt keine Tracking- oder Werbe-Cookies ein und nutzt keine Analyse-Tools.</p>\n<h2>Schriften</h2><p>Für die Darstellung der Schriften werden Google Fonts von Servern der Google LLC geladen. Dabei kann deine IP-Adresse an Google übermittelt werden.</p>\n<h2>Links zu LinkedIn und Instagram</h2><p>Im Footer verlinke ich meine Profile bei LinkedIn und Instagram. Es sind reine Links ohne eingebettete Plugins. Erst wenn du darauf klickst, gelten die Datenschutzbestimmungen der jeweiligen Anbieter.</p>\n<h2>Deine Rechte</h2><p>Du kannst jederzeit Auskunft über deine gespeicherten Daten verlangen sowie deren Berichtigung oder Löschung. Schreib dazu eine E-Mail an melina.gast@gmx.ch.</p>\n<h2>Änderungen</h2><p>Ich kann diese Erklärung anpassen, wenn sich die Website oder die Rechtslage ändert. Stand: November 2026.</p>"}}
NOWDOC_END, true);
    $log = [];
    foreach ($data['projects'] as $title => $p) {
        $found = get_posts(['post_type' => 'project', 'title' => $title, 'numberposts' => 1, 'post_status' => 'any']);
        if (!$found) { $log[] = "NICHT gefunden: $title"; continue; }
        $id = $found[0]->ID;
        carbon_set_post_meta($id, 'einleitung', implode("\n", array_map(fn($t) => '<p>' . esc_html($t) . '</p>', $p['einleitung'])));
        carbon_set_post_meta($id, 'aufgaben', array_map(fn($t) => ['_type' => '_', 'aufgabe' => $t], $p['aufgaben']));
        carbon_set_post_meta($id, 'ergebnis_karten', array_map(fn($k) => ['_type' => '_', 'title' => $k[0], 'text' => $k[1]], $p['karten']));
        carbon_set_post_meta($id, 'prozess_text', $p['prozess']);
        carbon_set_post_meta($id, 'prozess_schritte', array_map(fn($t) => ['_type' => '_', 'schritt' => $t], $p['schritte']));
        carbon_set_post_meta($id, 'mitarbeit', $p['mitarbeit']);
        carbon_set_post_meta($id, 'links', array_map(fn($l) => ['_type' => '_', 'titel' => $l[0], 'url' => $l[1]], $p['links']));
        $log[] = "Texte gesetzt: $title";
    }
    foreach ($data['legal'] as $title => $html) {
        $found = get_posts(['post_type' => 'page', 'title' => $title, 'numberposts' => 1, 'post_status' => 'any']);
        if (!$found) { $log[] = "Seite NICHT gefunden: $title"; continue; }
        $script = 'Rechtliches';
        carbon_set_post_meta($found[0]->ID, 'modules', [
            ['_type' => 'seitenkopf', 'title' => $title, 'script' => $script, 'text' => ''],
            ['_type' => 'textblock', 'title' => '', 'text' => $html],
        ]);
        $log[] = "Rechtstext gesetzt: $title";
    }
    echo implode("\n", $log);
    exit;
});
